/**
 * Customers — Frontend types.
 */

// ---------------------------------------------------------------------------
// Customer shapes (mirroring backend DTOs)
// ---------------------------------------------------------------------------

/** Compact customer shape for dropdown selectors. */
export interface CustomerSelectorItem {
  /** Unique customer identifier */
  id: string
  /** Human-readable name: "firstName lastName" for private, companyName for company */
  displayName: string
  /** 'private' or 'company' */
  type: 'private' | 'company'
}

/** Full customer detail returned by CRUD endpoints. */
export interface CustomerDetail {
  /** Unique customer identifier (client-generated UUID) */
  id: string
  /** Human-readable name: "firstName lastName" for private, companyName for company */
  displayName: string
  /** 'private' or 'company' */
  type: 'private' | 'company'
  /** First name — required for private customers */
  firstName?: string
  /** Last name — required for private customers */
  lastName?: string
  /** Company name — required for company customers */
  companyName?: string
  /** VAT ID — for company customers */
  vatId: string | null
  /** Phone number (loose validation: min 1, max 50 chars) */
  phone: string | null
  /** Email address (loose validation: min 1, max 50 chars) */
  email: string | null
  /** Street name */
  street: string | null
  /** Building/house number */
  number: string | null
  /** Apartment/unit number */
  bus: string | null
  /** Postal / ZIP code */
  postalCode: string | null
  /** City */
  city: string | null
  /** Country code (default: 'BE') */
  country: string
  // Index signature required by DataTable<T extends Record<string, unknown>>
  [key: string]: unknown
}

/** Display name computed from customer type and fields. */
export function getDisplayName(customer: CustomerDetail): string {
  return customer.type === 'private'
    ? [customer.firstName, customer.lastName].filter(Boolean).join(' ').trim() || ''
    : (customer.companyName ?? '')
}

// ---------------------------------------------------------------------------
// Pagination shapes
// ---------------------------------------------------------------------------

/** Paginated response from the management list endpoint. */
export interface CustomerPaginatedResponse {
  customers: CustomerDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

/**
 * Customers — API client functions.
 */

import type { CustomerPaginatedResponse, CustomerDetail } from './types.js'

const BASE_URL = '' // relative to current origin

// ---------------------------------------------------------------------------
// Management List (paginated + searchable)
// ---------------------------------------------------------------------------

export async function fetchCustomers({
  search,
  page = 1,
  pageSize = 25,
}: {
  search?: string
  page?: number
  pageSize?: number
}): Promise<CustomerPaginatedResponse> {
  const params = new URLSearchParams()

  if (search !== undefined && search !== '') {
    params.set('search', search)
  }
  params.set('page', String(page))
  params.set('pageSize', String(pageSize))

  const response = await fetch(`${BASE_URL}/api/customers?${params}`)

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to load customers: ${response.status}`)
  }

  return response.json() as Promise<CustomerPaginatedResponse>
}

// ---------------------------------------------------------------------------
// Single Customer Operations
// ---------------------------------------------------------------------------

export async function fetchCustomerById(id: string): Promise<CustomerDetail> {
  const response = await fetch(`${BASE_URL}/api/customers/${id}`)

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to load customer: ${response.status}`)
  }

  return response.json() as Promise<CustomerDetail>
}

// ---------------------------------------------------------------------------
// Create Customer
// ---------------------------------------------------------------------------

export async function createCustomer(data: Record<string, unknown>): Promise<CustomerDetail> {
  const response = await fetch(`${BASE_URL}/api/customers`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  })

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to create customer: ${response.status}`)
  }

  return response.json() as Promise<CustomerDetail>
}

// ---------------------------------------------------------------------------
// Update Customer
// ---------------------------------------------------------------------------

export async function updateCustomer(
  id: string,
  data: Record<string, unknown>
): Promise<CustomerDetail> {
  const response = await fetch(`${BASE_URL}/api/customers/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  })

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to update customer: ${response.status}`)
  }

  return response.json() as Promise<CustomerDetail>
}

// ---------------------------------------------------------------------------
// Delete Customer
// ---------------------------------------------------------------------------

export async function deleteCustomer(id: string): Promise<{ success: boolean }> {
  const response = await fetch(`${BASE_URL}/api/customers/${id}`, {
    method: 'DELETE',
  })

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to delete customer: ${response.status}`)
  }

  return response.json() as Promise<{ success: boolean }>
}

/**
 * useCustomers — Data fetching hook for the customer management list.
 *
 * Handles:
 * - Initial data load via GET /api/customers (paginated)
 * - Debounced search filtering across name, email, phone fields
 * - Pagination state management (25 per page by default)
 * - Loading and error states
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { fetchCustomers } from '../api.js'
import type { CustomerDetail, CustomerPaginatedResponse } from '../types.js'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_PAGE_SIZE = 25
const SEARCH_DEBOUNCE_MS = 300

// ---------------------------------------------------------------------------
// Hook State & Actions Interfaces
// ---------------------------------------------------------------------------

interface UseCustomersState {
  /** Paginated customer data */
  customers: CustomerDetail[]
  /** Total number of matching customers (for pagination) */
  totalItems: number
  /** Current page number (1-indexed) */
  currentPage: number
  /** Items per page */
  pageSize: number
  /** Total pages based on current search results */
  totalPages: number
  /** Current search term */
  searchTerm: string
  /** Whether data is currently being fetched */
  isLoading: boolean
  /** Error message from failed API calls, or null */
  error: string | null
}

interface UseCustomersActions {
  /** Set the search term (triggers debounced fetch) */
  setSearchTerm: (term: string) => void
  /** Navigate to a specific page */
  goToPage: (page: number) => void
  /** Reset pagination to page 1 and refetch */
  refresh: () => void
}

export type UseCustomersResult = UseCustomersState & UseCustomersActions

// ---------------------------------------------------------------------------
// Hook Implementation
// ---------------------------------------------------------------------------

/**
 * Custom hook for fetching and managing the customer list.
 *
 * Provides paginated results with debounced search filtering.
 */
export function useCustomers(): UseCustomersResult {
  const [customers, setCustomers] = useState<CustomerDetail[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize] = useState(DEFAULT_PAGE_SIZE)
  const [searchTerm, setSearchTermState] = useState('')
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Ref for debounce timer
  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  // Debounced search term — actual value used in API calls
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('')

  // -----------------------------------------------------------------------
  // Data fetching
  // -----------------------------------------------------------------------

  const fetchCustomerData = useCallback(async () => {
    setIsLoading(true)
    setError(null)

    try {
      const response: CustomerPaginatedResponse = await fetchCustomers({
        search: debouncedSearchTerm || undefined,
        page: currentPage,
        pageSize,
      })

      setCustomers(response.customers)
      setTotalItems(response.totalItems)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load customers'
      setError(message)
      setCustomers([])
      setTotalItems(0)
    } finally {
      setIsLoading(false)
    }
  }, [debouncedSearchTerm, currentPage, pageSize])

  // -----------------------------------------------------------------------
  // Search debouncing
  // -----------------------------------------------------------------------

  const setSearchTerm = useCallback((term: string) => {
    setSearchTermState(term)

    // Clear existing timer
    if (searchTimerRef.current) {
      clearTimeout(searchTimerRef.current)
    }

    // Set new debounce timer
    searchTimerRef.current = setTimeout(() => {
      setDebouncedSearchTerm(term)
      // Reset to page 1 when search changes
      setCurrentPage(1)
    }, SEARCH_DEBOUNCE_MS)
  }, [])

  // -----------------------------------------------------------------------
  // Pagination
  // -----------------------------------------------------------------------

  const goToPage = useCallback((page: number) => {
    setCurrentPage(page)
  }, [])

  const refresh = useCallback(() => {
    fetchCustomerData()
  }, [fetchCustomerData])

  // -----------------------------------------------------------------------
  // Derived state
  // -----------------------------------------------------------------------

  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize))

  // -----------------------------------------------------------------------
  // Effects
  // -----------------------------------------------------------------------

  // Fetch data when search term or page changes
  useEffect(() => {
    fetchCustomerData()
  }, [fetchCustomerData])

  // Cleanup debounce timer on unmount
  useEffect(() => {
    return () => {
      if (searchTimerRef.current) {
        clearTimeout(searchTimerRef.current)
      }
    }
  }, [])

  // -----------------------------------------------------------------------
  // Return
  // -----------------------------------------------------------------------

  return {
    customers,
    totalItems,
    currentPage,
    pageSize,
    totalPages,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  }
}

/**
 * CustomersPage — Management list page for customers.
 *
 * Displays a searchable, paginated DataTable with columns for:
 * - Name (computed from type)
 * - Type badge (Private/Company)
 * - Contact info (email/phone)
 * - Actions (Edit/Delete buttons)
 */

import { useCallback, useState } from 'react'
import toast from 'react-hot-toast'
import { useCustomers } from '../hooks/useCustomers.js'
import {
  DataTable,
  type DataTableColumn,
} from '@/components/ui/DataTable.js'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog.js'
import { Button } from '@/components/ui/button.js'
import type { CustomerDetail } from '../types.js'
import { getDisplayName } from '../types.js'
import { CustomerFormDialog } from './CustomerFormDialog.js'

// ---------------------------------------------------------------------------
// Column Definitions
// ---------------------------------------------------------------------------

function TypeBadge({ type }: { type: 'private' | 'company' }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        type === 'private'
          ? 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'
          : 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300'
      }`}
    >
      {type === 'private' ? 'Private' : 'Company'}
    </span>
  )
}

function ContactInfo({ customer }: { customer: CustomerDetail }) {
  const contacts = [customer.email, customer.phone].filter(Boolean)

  if (contacts.length === 0) {
    return <span className="text-muted-foreground">—</span>
  }

  return (
    <div className="flex flex-col gap-0.5 text-sm">
      {customer.email && (
        <a href={`mailto:${customer.email}`} className="text-blue-600 hover:underline">
          {customer.email}
        </a>
      )}
      {customer.phone && (
        <span>{customer.phone}</span>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Page Component
// ---------------------------------------------------------------------------

export function CustomersPage() {
  const {
    customers,
    totalItems,
    currentPage,
    pageSize,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  } = useCustomers()

  // -----------------------------------------------------------------------
  // Form dialog state (create + edit via single component)
  // -----------------------------------------------------------------------

  const [formDialogOpen, setFormDialogOpen] = useState(false)
  const [editingCustomer, setEditingCustomer] = useState<CustomerDetail | null>(null)

  // -----------------------------------------------------------------------
  // Delete confirmation dialog state
  // -----------------------------------------------------------------------

  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)
  const [deletingCustomer, setDeletingCustomer] = useState<CustomerDetail | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  // -----------------------------------------------------------------------
  // Action handlers — Edit, Delete, Create
  // -----------------------------------------------------------------------

  const openCreateDialog = useCallback(() => {
    setEditingCustomer(null)
    setFormDialogOpen(true)
  }, [])

  const handleEdit = useCallback((customer: CustomerDetail) => {
    setEditingCustomer(customer)
    setFormDialogOpen(true)
  }, [])

  const openDeleteDialog = useCallback((customer: CustomerDetail) => {
    setDeletingCustomer(customer)
    setDeleteDialogOpen(true)
  }, [])

  const handleConfirmDelete = useCallback(async () => {
    if (!deletingCustomer) return

    setIsDeleting(true)

    try {
      const response = await fetch(`/api/customers/${deletingCustomer.id}`, { method: 'DELETE' })

      if (!response.ok) {
        const body = await response.json().catch(() => ({}))
        const message = (body as { error?: string }).error ?? `Delete failed: ${response.status}`
        // Show toast for blocked deletes and other errors
        toast.error(message)
        return
      }

      setDeleteDialogOpen(false)
      toast.success('Customer deleted successfully')
      refresh()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to delete customer'
      toast.error(message)
    } finally {
      setIsDeleting(false)
    }
  }, [deletingCustomer, refresh])

  const closeDeleteDialog = useCallback(() => {
    setDeleteDialogOpen(false)
    setDeletingCustomer(null)
    setIsDeleting(false)
  }, [])

  // -----------------------------------------------------------------------
  // Form dialog callbacks
  // -----------------------------------------------------------------------

  const handleFormSaveSuccess = useCallback(() => {
    toast.success(editingCustomer ? 'Customer updated successfully' : 'Customer created successfully')
    refresh()
  }, [editingCustomer, refresh])

  // -----------------------------------------------------------------------
  // Column definitions for DataTable
  // ---------------------------------------------------------------------------

  const columns: DataTableColumn<CustomerDetail>[] = [
    {
      key: 'name',
      header: 'Name',
      render: (customer: CustomerDetail) => (
        <span className="font-medium">{getDisplayName(customer)}</span>
      ),
    },
    {
      key: 'type',
      header: 'Type',
      render: (customer: CustomerDetail) => (
        <TypeBadge type={customer.type} />
      ),
    },
    {
      key: 'contact',
      header: 'Contact',
      render: (customer: CustomerDetail) => (
        <ContactInfo customer={customer} />
      ),
    },
    {
      key: 'actions',
      header: 'Actions',
      render: (customer: CustomerDetail) => (
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => handleEdit(customer)}
          >
            Edit
          </Button>
          <Button
            variant="destructive"
            size="sm"
            onClick={() => openDeleteDialog(customer)}
          >
            Delete
          </Button>
        </div>
      ),
    },
  ]

  // -----------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <div className="space-y-6">
      {/* Page header */}
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Customers</h1>
        <p className="text-muted-foreground mt-1">
          Manage your customer records. Search, filter, and paginate through the list.
        </p>
      </div>

      {/* Error banner */}
      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
          <p className="font-medium">Error loading customers</p>
          <p>{error}</p>
          <Button variant="outline" size="sm" onClick={refresh} className="mt-2">
            Retry
          </Button>
        </div>
      )}

      {/* Toolbar — New Customer button */}
      <div className="flex justify-end">
        <Button onClick={openCreateDialog}>New Customer</Button>
      </div>

      {/* DataTable */}
      <DataTable<CustomerDetail>
        data={customers}
        columns={columns}
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        totalItems={totalItems}
        currentPage={currentPage}
        pageSize={pageSize}
        onPageChange={goToPage}
        isLoading={isLoading}
        emptyMessage="No customers found"
      />

      {/* Form dialog (create + edit) */}
      <CustomerFormDialog
        open={formDialogOpen}
        onOpenChange={(open) => {
          setFormDialogOpen(open)
          if (!open) {
            setEditingCustomer(null)
          }
        }}
        editingCustomer={editingCustomer}
        onSaveSuccess={handleFormSaveSuccess}
      />

      {/* Delete confirmation dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={closeDeleteDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Delete customer</DialogTitle>
            <DialogDescription>
              Are you sure you want to delete{' '}
              <strong>{deletingCustomer ? getDisplayName(deletingCustomer) : ''}</strong>?
              This action cannot be undone. If the customer has related records
              (sales, invoices, quotes, repairs), deletion will be blocked.
            </DialogDescription>
          </DialogHeader>



          <DialogFooter>
            <Button variant="outline" onClick={closeDeleteDialog} disabled={isDeleting}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleConfirmDelete}
              disabled={isDeleting || !deletingCustomer}
            >
              {isDeleting ? 'Deleting...' : 'Delete'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Sales History feature types — explicit interfaces, never Drizzle inference
// ---------------------------------------------------------------------------

/** A single sale record as returned by GET /api/sales.
 * Keys match Drizzle camelCase property names (backend serialises via Object.fromEntries). */
export interface SaleRecord {
  id: string
  saleNumber: string // e.g. "SA-0042"
  customerId: string | null
  sourceType: string
  sourceId: string | null
  status: 'completed' | 'voided'
  subtotalNet: number // ex-tax cents
  vatTotal: number // VAT in cents
  totalGross: number // incl-tax cents
  createdAt: string // ISO timestamp
}

/** Response shape for GET /api/sales */
export interface SalesListResponse {
  sales: SaleRecord[]
  total: number
}

/** Error response from PATCH /api/sales/:id/void */
export interface VoidError {
  error: string
  code?: 'NOT_FOUND' | 'ALREADY_VOIDED' | 'INTERNAL_ERROR'
}

/** Shape of customer lookup cache (id → displayName) */
export interface CustomerNameMap {
  [id: string]: string
}

import type { SalesListResponse, VoidError } from './types.js'

// ---------------------------------------------------------------------------
// Sales History API — fetches and voids past sales
//
// Calls the server's GET /api/sales and PATCH /api/sales/:id/void endpoints.
// Uses raw fetch (not apiClient) to match the pattern used by checkout.ts,
// since the server returns plain JSON without an envelope wrapper.
// ---------------------------------------------------------------------------

const API_BASE = ''

// ============================================================================
// Fetch Sales List
// ============================================================================

/**
 * Fetch the sales history list.
 *
 * @param limit — Maximum number of recent sales to return (default: 50)
 * @returns Sales list response with array and total count
 */
export async function fetchSalesList(limit = 50): Promise<SalesListResponse> {
  const response = await fetch(`${API_BASE}/api/sales?limit=${limit}`)

  if (!response.ok) {
    throw new Error(`Failed to fetch sales list: ${response.status}`)
  }

  return (await response.json()) as SalesListResponse
}

// ============================================================================
// Void Sale
// ============================================================================

/**
 * Void a completed sale by setting its status to 'voided'.
 *
 * Does NOT reverse stock movements or payments (per domain rule R13).
 * Guards against voiding already-voided sales.
 *
 * @param saleId — UUID of the sale to void
 * @returns Updated sale record with status = 'voided'
 */
export async function voidSale(saleId: string): Promise<void> {
  const response = await fetch(`${API_BASE}/api/sales/${saleId}/void`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
  })

  if (!response.ok) {
    const errorBody = (await response.json().catch(() => ({}))) as VoidError
    throw new Error(errorBody.error ?? `Void failed with status ${response.status}`)
  }
}

/**
 * Repair feature types — mirrors shared types for frontend use.
 */

// ============================================================================
// Repair Status
// ============================================================================

export type RepairStatus = 'intake' | 'in_progress' | 'on_hold' | 'verified' | 'ready' | 'completed' | 'cancelled'

/** Color mapping for status badges */
export const STATUS_COLORS: Record<RepairStatus, string> = {
  intake: 'bg-blue-100 text-blue-800',
  in_progress: 'bg-yellow-100 text-yellow-800',
  on_hold: 'bg-orange-100 text-orange-800',
  verified: 'bg-purple-100 text-purple-800',
  ready: 'bg-green-100 text-green-800',
  completed: 'bg-gray-100 text-gray-800',
  cancelled: 'bg-red-100 text-red-800',
}

// ============================================================================
// Repair Detail Shape (matches API response)
// ============================================================================

export interface RepairDetail {
  id: string
  bicycleId: string
  assignedTo: string | null
  status: RepairStatus
  customerNotes: string | null
  internalNotes: string | null
  holdReason: 'waiting_parts' | 'awaiting_customer_approval' | 'other' | null
  holdReasonNote: string | null
  plannedDate: number | null
  pickupDate: number | null
  completedAt: number | null
  createdAt: number
}

/** Repair detail enriched with customer name and bicycle info for list display */
export interface RepairDetailWithCustomer extends Omit<RepairDetail, 'bicycleId'> {
  customerName: string | null
  bicycleBrand: string
  bicycleModel: string
  bicycleColor: string | null
}

// ============================================================================
// Intake Form Types
// ============================================================================

/** Customer selection mode */
export type CustomerMode = 'existing' | 'new'

/** Bicycle selection mode */
export type BicycleMode = 'select_existing' | 'create_new'

/** Compact customer shape for selectors — matches GET /api/customers response. */
export interface IntakeCustomer {
  id: string
  displayName: string
  type: 'private' | 'company'
}

/** Compact bicycle shape for selectors */
export interface IntakeBicycle {
  id: string
  brand: string
  model: string
  color: string | null
  year: number | null
}

/** Customer with their bicycles — returned during intake lookup */
export interface CustomerWithBicycles extends IntakeCustomer {
  bicycles: IntakeBicycle[]
}

/** Form data for the repair intake modal */
export interface RepairIntakeFormData {
  // Customer section
  customerMode: CustomerMode
  existingCustomerId?: string
  newFirstName?: string
  newLastName?: string
  newCompanyName?: string
  newPhone: string
  newEmail: string

  // Bicycle section
  bicycleMode: BicycleMode
  existingBicycleId?: string
  newBrand: string
  newModel: string
  newColor: string

  // Notes
  customerNotes: string

  // Optional scheduling dates (epoch ms, nullable)
  plannedDate?: number | null
  pickupDate?: number | null
}

/** Default empty form state */
export const createEmptyIntakeForm = (): RepairIntakeFormData => ({
  customerMode: 'existing',
  newPhone: '',
  newEmail: '',
  bicycleMode: 'select_existing',
  newBrand: '',
  newModel: '',
  newColor: '',
  customerNotes: '',
})

import { Hono } from 'hono'
import {
  createDirectSale,
  voidSale,
  type SaleResult,
  InsufficientStockError,
  SaleNotFoundError,
  listSales,
  findSaleById,
  findLineItemsBySaleId,
  findPaymentsBySaleId,
  findMovementsBySaleId
} from '../services/sale.service.js'

const salesRoutes = new Hono()

// ============================================================================
// POST /sales — Create a direct sale
// ============================================================================

/**
 * Error response shape.
 */
interface ErrorResponse {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

salesRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result: SaleResult = await createDirectSale(rawInput)

    return c.json(
      {
        sale: Object.fromEntries(Object.entries(result.sale)),
        payment: Object.fromEntries(Object.entries(result.payment)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item)))
      },
      201
    )
  } catch (err) {
    if (err instanceof InsufficientStockError) {
      return c.json(
        {
          error: 'Insufficient stock',
          code: 'INSUFFICIENT_STOCK',
          shortfalls: err.shortfalls
        } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid sale input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /sales] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /sales — List recent sales history
// ============================================================================

interface SalesListResponse {
  /** Array of sale records (newest first) */
  sales: Record<string, unknown>[]
  /** Total count of all sales */
  total: number
}

salesRoutes.get('/', async (c) => {
