  if (bicycleIds.length === 0) return []

  const idsParam = bicycleIds.join(',')
  const response = await fetch(`${BASE_URL}/api/repairs?bicycleIds=${encodeURIComponent(idsParam)}&pageSize=50`)

  if (!response.ok) {
    throw new Error(`Failed to load repairs: ${response.status}`)
  }

  const data = (await response.json()) as { repairs: Record<string, unknown>[]; total: number }
  return data.repairs
}

