/**
 * useCustomerActivity — Fetches all activity data for a single customer.
 *
 * Aggregates sales, bicycles, orders, and repairs from existing endpoints.
 * Used by CustomerDetailPanel for client-side aggregation pattern.
 */

import { useState, useEffect, useCallback } from 'react'
import {
  fetchCustomerSales,
  fetchCustomerBicycles,
  fetchCustomerOrders,
  fetchRepairsByBicycleIds,
} from '../api.js'
import type { CustomerSale, CustomerBicycle, CustomerOrder, CustomerRepair } from '../types.js'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const VOLUME_LIMIT = 50

// ---------------------------------------------------------------------------
// Hook State & Result Interface
// ---------------------------------------------------------------------------

interface UseCustomerActivityResult {
  /** Sales history for this customer */
  sales: CustomerSale[]
  /** Bicycles owned by this customer */
  bicycles: CustomerBicycle[]
  /** Customer orders/reservations */
  orders: CustomerOrder[]
  /** Repairs across all customer bicycles (flat list) */
  repairs: CustomerRepair[]
  /** Whether any data is currently loading */
  isLoading: boolean
  /** Error message if fetch failed, null otherwise */
  error: string | null
  /** Whether the customer has ANY activity at all */
  hasActivity: boolean
}

// ---------------------------------------------------------------------------
// Hook Implementation
// ---------------------------------------------------------------------------

/**
 * Custom hook that aggregates all customer activity from existing endpoints.
 * Each section fetches independently — no "god" API endpoint needed.
 */
export function useCustomerActivity(customerId: string): UseCustomerActivityResult {
  const [sales, setSales] = useState<CustomerSale[]>([])
  const [bicycles, setBicycles] = useState<CustomerBicycle[]>([])
  const [orders, setOrders] = useState<CustomerOrder[]>([])
  const [repairs, setRepairs] = useState<CustomerRepair[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Derived: does the customer have any activity?
  const hasActivity = sales.length > 0 || bicycles.length > 0 || orders.length > 0 || repairs.length > 0

  const fetchData = useCallback(async () => {
    setIsLoading(true)
    setError(null)

    try {
      // Fetch all sections in parallel (except repairs which depends on bicycle IDs)
      const [salesData, bicyclesData, ordersData] = await Promise.all([
        fetchCustomerSales(customerId, VOLUME_LIMIT).catch(() => [] as CustomerSale[]),
        fetchCustomerBicycles(customerId).catch(() => [] as CustomerBicycle[]),
        fetchCustomerOrders(customerId).catch(() => [] as CustomerOrder[]),
      ])

      setSales(salesData)
      setBicycles(bicyclesData)
      setOrders(ordersData)

      // Fetch repairs for all customer bicycles (flat list, chronologically sorted)
      if (bicyclesData.length > 0) {
        const bicycleIds = bicyclesData.map(b => b.id)
        const repairsData = await fetchRepairsByBicycleIds(bicycleIds).catch(() => [] as Record<string, unknown>[])

        // Map raw repair data to CustomerRepair type and sort chronologically (oldest first)
        const typedRepairs: CustomerRepair[] = repairsData.map(r => ({
          id: r.id as string,
          bicycleId: r.bicycle_id as string,
          status: r.status as CustomerRepair['status'],
          plannedDate: r.planned_date as number | null,
          pickupDate: r.pickup_date as number | null,
          completedAt: r.completed_at as number | null,
          createdAt: r.created_at as number,
          bicycleBrand: r.bicycle_brand as string,
          bicycleModel: r.bicycle_model as string,
        })).sort((a, b) => a.createdAt - b.createdAt)

        setRepairs(typedRepairs.slice(0, VOLUME_LIMIT))
      } else {
        setRepairs([])
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load customer activity'
      setError(message)
    } finally {
      setIsLoading(false)
    }
  }, [customerId])

  useEffect(() => {
    fetchData()
  }, [fetchData])

  return {
    sales,
    bicycles,
    orders,
    repairs,
    isLoading,
    error,
    hasActivity,
  }
}

/**
 * CustomerDetailPanel — Single-pane view of a customer showing ALL their activity.
 *
 * Uses client-side aggregation from existing endpoints (no new "god" API endpoint).
 * Each section fetches independently and combines in the UI layer.
 */

import { useState, useMemo } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { formatCentsToEuro } from '@/shared/lib/utils.js'
import { Button } from '@/components/ui/button.js'
import type { CustomerDetail } from '../types.js'
import { getDisplayName } from '../types.js'
import { fetchCustomerById, fetchSaleDetail, fetchOrderDetail } from '../api.js'
import { useCustomerActivity } from '../hooks/useCustomerActivity.js'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const VOLUME_LIMIT = 50

// ---------------------------------------------------------------------------
// Utility Functions
// ---------------------------------------------------------------------------

/** Derive sale type badge label from sourceType */
function getSaleTypeLabel(sourceType: string): string {
  const labels: Record<string, string> = {
    direct_sale: 'POS Sale',
    repair: 'Repair Deposit',
    customer_order: 'Order',
    backorder: 'Backorder',
  }
  return labels[sourceType] ?? sourceType
}

/** Derive sale type badge color from sourceType */
function getSaleTypeColor(sourceType: string): string {
  const colors: Record<string, string> = {
    direct_sale: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
    repair: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300',
    customer_order: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300',
    backorder: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
  }
  return colors[sourceType] ?? 'bg-gray-100 text-gray-800'
}

/** Format epoch ms to readable date */
function formatDate(epochMs: number | null | undefined): string {
  if (!epochMs) return '—'
  return new Date(epochMs).toLocaleDateString('en-IE', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
  })
}

/** Format epoch ms to datetime */
function formatDateTime(epochMs: number | null | undefined): string {
  if (!epochMs) return '—'
  return new Date(epochMs).toLocaleDateString('en-IE', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  })
}

/** Repair status badge colors */
const REPAIR_STATUS_COLORS: Record<string, string> = {
  intake: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
  in_progress: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300',
  on_hold: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300',
  ready: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
  completed: 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300',
  cancelled: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300',
}

/** Order status badge colors */
const ORDER_STATUS_COLORS: Record<string, string> = {
  pending: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300',
  ordered: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
  ready: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
  fulfilled: 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300',
  cancelled: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300',
}

// ---------------------------------------------------------------------------
// Chevron Icon
// ---------------------------------------------------------------------------

function ChevronIcon({ expanded }: { expanded: boolean }) {
  return (
    <svg
      className={`w-4 h-4 transition-transform duration-200 ${expanded ? 'rotate-90' : ''}`}
      fill="none"
      viewBox="0 0 24 24"
      stroke="currentColor"
      strokeWidth={2}
    >
      <path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" />
    </svg>
  )
}

// ---------------------------------------------------------------------------
// Section: Sales History (green border)
// ---------------------------------------------------------------------------

function SalesHistorySection({ sales }: { sales: Array<{ id: string; saleNumber: string; sourceType: string; status: string; totalGross: number; createdAt: number }> }) {
  const [expandedSaleId, setExpandedSaleId] = useState<string | null>(null)
  const [saleDetails, setSaleDetails] = useState<Record<string, { lineItems: Record<string, unknown>[]; payments: Record<string, unknown>[] }>>({})

  const handleToggleExpand = async (saleId: string) => {
    if (expandedSaleId === saleId) {
      setExpandedSaleId(null)
      return
    }

    setExpandedSaleId(saleId)
    if (!saleDetails[saleId]) {
      try {
        const detail = await fetchSaleDetail(saleId)
        setSaleDetails(prev => ({ ...prev, [saleId]: detail }))
      } catch {
        // Silently fail — expanded content won't show but row still works
      }
    }
  }

  if (sales.length === 0) return null

  return (
    <div className="border-l-4 border-green-500 rounded-r-lg bg-card">
      <div className="px-4 py-3 font-semibold text-sm text-muted-foreground uppercase tracking-wider">
        Sales History ({sales.length})
      </div>
      <div className="divide-y divide-border">
        {sales.map(sale => (
          <div key={sale.id}>
            {/* Summary row */}
            <button
              onClick={() => handleToggleExpand(sale.id)}
              className="w-full flex items-center justify-between px-4 py-3 hover:bg-muted/50 transition-colors text-left"
            >
              <div className="flex items-center gap-3">
                <ChevronIcon expanded={expandedSaleId === sale.id} />
                <span className="font-mono text-xs text-muted-foreground">{sale.saleNumber}</span>
                <span>{formatDateTime(sale.createdAt)}</span>
                <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${getSaleTypeColor(sale.sourceType)}`}>
                  {getSaleTypeLabel(sale.sourceType)}
                </span>
              </div>
              <div className="flex items-center gap-3">
                <span className="font-medium tabular-nums">{formatCentsToEuro(sale.totalGross)}</span>
                <span className={`text-xs ${sale.status === 'voided' ? 'text-red-500' : 'text-green-600 dark:text-green-400'}`}>
                  {sale.status}
                </span>
              </div>
            </button>

            {/* Expanded detail */}
            {expandedSaleId === sale.id && saleDetails[sale.id] && (
              <div className="px-4 py-3 bg-muted/20 space-y-3">
                {/* Line Items */}
                <div>
                  <div className="text-xs font-medium text-muted-foreground mb-1.5">Items</div>
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="text-muted-foreground">
                        <th className="text-left py-1 pr-4">Description</th>
                        <th className="text-center py-1 px-2">Qty</th>
                        <th className="text-right py-1 pl-4">Price</th>
                        <th className="text-right py-1 pl-4">Total</th>
                      </tr>
                    </thead>
                    <tbody>
                      {saleDetails[sale.id].lineItems.map((item: Record<string, unknown>) => (
                        <tr key={item.id as string} className="border-t border-border/50">
                          <td className="py-1.5 pr-4">{(item.description as string) ?? '—'}</td>
                          <td className="text-center py-1.5 px-2 tabular-nums">{item.quantity as number}</td>
                          <td className="text-right py-1.5 pl-4 tabular-nums text-muted-foreground">
                            {formatCentsToEuro(item.unitPriceNet as number)}
                          </td>
                          <td className="text-right py-1.5 pl-4 tabular-nums font-medium">
                            {formatCentsToEuro(item.lineGrossTotal as number)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                {/* Payments */}
                <div>
                  <div className="text-xs font-medium text-muted-foreground mb-1.5">Payments</div>
                  <div className="space-y-1">
                    {saleDetails[sale.id].payments.map((payment: Record<string, unknown>) => (
                      <div key={payment.id as string} className="flex items-center justify-between text-sm">
                        <span className="capitalize">{payment.method as string}</span>
                        <span className="tabular-nums font-medium">{formatCentsToEuro(payment.allocatedAmount as number)}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Section: Owned Bicycles (blue border)
// ---------------------------------------------------------------------------

function OwnedBicyclesSection({ bicycles }: { bicycles: Array<{ id: string; source: string; brand: string; model: string; year: number | null; color: string | null; isLease: boolean; status: string }> }) {
  const [expandedBikeId, setExpandedBikeId] = useState<string | null>(null)

  if (bicycles.length === 0) return null

  return (
    <div className="border-l-4 border-blue-500 rounded-r-lg bg-card">
      <div className="px-4 py-3 font-semibold text-sm text-muted-foreground uppercase tracking-wider">
        Owned Bicycles ({bicycles.length})
      </div>
      <div className="divide-y divide-border">
        {bicycles.map(bike => (
          <div key={bike.id}>
            {/* Summary row */}
            <button
              onClick={() => setExpandedBikeId(expandedBikeId === bike.id ? null : bike.id)}
              className="w-full flex items-center justify-between px-4 py-3 hover:bg-muted/50 transition-colors text-left"
            >
              <div className="flex items-center gap-3">
                <ChevronIcon expanded={expandedBikeId === bike.id} />
                <span>
                  {bike.brand} {bike.model}
                  {bike.year ? ` (${bike.year})` : ''}
                  {bike.color ? ` — ${bike.color}` : ''}
                </span>
              </div>
              <div className="flex items-center gap-2">
                <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${bike.source === 'inventory' ? 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300' : 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'}`}>
                  {bike.source === 'inventory' ? 'Inventory' : 'Customer Owned'}
                </span>
                {bike.isLease && (
                  <span className="inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300">
                    Lease
                  </span>
                )}
              </div>
            </button>

            {/* Expanded: repair history per bike */}
            {expandedBikeId === bike.id && (
              <div className="px-4 py-3 bg-muted/20 text-sm">
                <div className="text-xs font-medium text-muted-foreground mb-1.5">Repair History</div>
                <p className="text-muted-foreground italic">View repairs in the Repairs section below (sorted across all bicycles)</p>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Section: Customer Orders / Reservations (orange border)
// ---------------------------------------------------------------------------

function CustomerOrdersSection({ orders }: { orders: Array<{ id: string; orderNumber: string; status: string; totalPriceNet: number; expectedDeliveryDate: number | null; createdAt: number }> }) {
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null)
  const [orderDetails, setOrderDetails] = useState<Record<string, { lineItems: Record<string, unknown>[]; depositPaid: number }>>({})

  const handleToggleExpand = async (orderId: string) => {
    if (expandedOrderId === orderId) {
      setExpandedOrderId(null)
      return
    }

    setExpandedOrderId(orderId)
    if (!orderDetails[orderId]) {
      try {
        const detail = await fetchOrderDetail(orderId)
        setOrderDetails(prev => ({ ...prev, [orderId]: detail }))
      } catch {
        // Silently fail
      }
    }
  }

  if (orders.length === 0) return null

  return (
    <div className="border-l-4 border-orange-500 rounded-r-lg bg-card">
      <div className="px-4 py-3 font-semibold text-sm text-muted-foreground uppercase tracking-wider">
        Orders / Reservations ({orders.length})
      </div>
      <div className="divide-y divide-border">
        {orders.map(order => (
          <div key={order.id}>
            {/* Summary row */}
            <button
              onClick={() => handleToggleExpand(order.id)}
              className="w-full flex items-center justify-between px-4 py-3 hover:bg-muted/50 transition-colors text-left"
            >
              <div className="flex items-center gap-3">
                <ChevronIcon expanded={expandedOrderId === order.id} />
                <span className="font-mono text-xs">{order.orderNumber}</span>
                <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${ORDER_STATUS_COLORS[order.status] ?? 'bg-gray-100 text-gray-800'}`}>
                  {order.status}
                </span>
              </div>
              <div className="flex items-center gap-3">
                {order.expectedDeliveryDate && (
                  <span className="text-xs text-muted-foreground">ETA: {formatDate(order.expectedDeliveryDate)}</span>
                )}
                <span className="font-medium tabular-nums">{formatCentsToEuro(order.totalPriceNet)}</span>
              </div>
            </button>

            {/* Expanded detail */}
            {expandedOrderId === order.id && orderDetails[order.id] && (
              <div className="px-4 py-3 bg-muted/20 space-y-3">
                {/* Line Items */}
                <div>
                  <div className="text-xs font-medium text-muted-foreground mb-1.5">Line Items</div>
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="text-muted-foreground">
                        <th className="text-left py-1 pr-4">Description</th>
                        <th className="text-center py-1 px-2">Qty</th>
                        <th className="text-right py-1 pl-4">Total</th>
                      </tr>
                    </thead>
                    <tbody>
                      {orderDetails[order.id].lineItems.map((item: Record<string, unknown>) => (
                        <tr key={item.id as string} className="border-t border-border/50">
                          <td className="py-1.5 pr-4">{(item.description as string) ?? '—'}</td>
                          <td className="text-center py-1.5 px-2 tabular-nums">{item.quantity as number}</td>
                          <td className="text-right py-1.5 pl-4 tabular-nums font-medium">
                            {formatCentsToEuro(item.lineGrossTotal as number)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                {/* Deposit Info */}
                <div className="flex items-center justify-between text-sm">
                  <span className="text-muted-foreground">Deposit Paid</span>
                  <span className="tabular-nums font-medium">{formatCentsToEuro(orderDetails[order.id].depositPaid)}</span>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Section: Repairs (purple border) — flat, chronologically sorted
// ---------------------------------------------------------------------------

function RepairsSection({ repairs }: { repairs: Array<{ id: string; status: string; plannedDate: number | null; bicycleBrand: string; bicycleModel: string }> }) {
  if (repairs.length === 0) return null

  return (
    <div className="border-l-4 border-purple-600 rounded-r-lg bg-card">
      <div className="px-4 py-3 font-semibold text-sm text-muted-foreground uppercase tracking-wider">
        Repairs ({repairs.length})
      </div>
      <div className="divide-y divide-border">
        {repairs.map(repair => (
          <div key={repair.id} className="flex items-center justify-between px-4 py-3 hover:bg-muted/50 transition-colors">
            <div className="flex items-center gap-3">
              <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${REPAIR_STATUS_COLORS[repair.status] ?? 'bg-gray-100 text-gray-800'}`}>
                {repair.status}
              </span>
              <span className="text-sm">
                {repair.bicycleBrand} {repair.bicycleModel}
              </span>
            </div>
            <div className="flex items-center gap-3">
              {repair.plannedDate && (
                <span className="text-xs text-muted-foreground">{formatDate(repair.plannedDate)}</span>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Summary Footer
// ---------------------------------------------------------------------------

function SummaryFooter({ sales, repairs, bicycles }: { sales: unknown[]; repairs: unknown[]; bicycles: unknown[] }) {
  const totalSales = useMemo(() => {
    return (sales as Array<{ totalGross: number }>).reduce((sum, s) => sum + s.totalGross, 0)
  }, [sales])

  return (
    <div className="flex items-center justify-between px-4 py-3 bg-muted/50 rounded-lg text-sm">
      <div className="flex items-center gap-6">
        <span>
          <span className="text-muted-foreground">Total Sales: </span>
          <span className="font-medium tabular-nums">{formatCentsToEuro(totalSales)}</span>
        </span>
        <span>
          <span className="text-muted-foreground">Repairs: </span>
          <span className="font-medium">{repairs.length}</span>
        </span>
        <span>
          <span className="text-muted-foreground">Bicycles: </span>
          <span className="font-medium">{bicycles.length}</span>
        </span>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Main Component — CustomerDetailPanel
// ---------------------------------------------------------------------------

export function CustomerDetailPanel() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()

  const [customer, setCustomer] = useState<CustomerDetail | null>(null)
  const [loadingCustomer, setLoadingCustomer] = useState(true)

  // Fetch customer detail
  useEffect(() => {
    if (!id) return
    setLoadingCustomer(true)
    fetchCustomerById(id)
      .then(data => setCustomer(data))
      .catch(() => setCustomer(null))
      .finally(() => setLoadingCustomer(false))
  }, [id])

  // Fetch all activity data (client-side aggregation)
  const { sales, bicycles, orders, repairs, isLoading: loadingActivity, error, hasActivity } = useCustomerActivity(id ?? '')

  if (!id || loadingCustomer) {
    return (
      <div className="flex items-center justify-center h-full text-muted-foreground">
        Loading customer...
      </div>
    )
  }

  if (!customer) {
    return (
      <div className="flex flex-col items-center justify-center h-full gap-4 text-muted-foreground">
        <p className="text-lg font-medium">Customer not found</p>
        <Button variant="outline" onClick={() => navigate('/customers')}>Back to Customers</Button>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Header */}
      <div className="shrink-0 border-b bg-card px-6 py-4 space-y-2">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold tracking-tight">{getDisplayName(customer)}</h1>
            <p className="text-sm text-muted-foreground mt-0.5">
              {customer.type === 'private' ? 'Private Customer' : 'Company'}
              {customer.phone && ` · ${customer.phone}`}
            </p>
          </div>
          <Button variant="outline" size="sm" onClick={() => navigate('/customers')}>
            ← Back to List
          </Button>
        </div>

        {/* Email notification indicator */}
        {customer.email && (
          <div className="flex items-center gap-2 text-sm">
            <span className="text-muted-foreground">{customer.email}</span>
            <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${
              customer.notificationPreference === 'email'
                ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300'
                : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400'
            }`}>
              {customer.notificationPreference === 'email' ? 'Email notifications active' : 'No email preference set'}
            </span>
          </div>
        )}

        {/* Business Details (conditional) */}
        {(customer.companyName || customer.vatId) && (
          <div className="mt-2 p-3 bg-muted/50 rounded-lg text-sm space-y-1">
            {customer.companyName && (
              <div>
                <span className="text-muted-foreground">Company: </span>
                <span className="font-medium">{customer.companyName}</span>
              </div>
            )}
            {customer.vatId && (
              <div>
                <span className="text-muted-foreground">VAT ID: </span>
                <span className="font-mono text-xs">{customer.vatId}</span>
              </div>
            )}
          </div>
        )}

        {/* Address (conditional) */}
        {(customer.street || customer.city) && (
          <div className="mt-2 p-3 bg-muted/50 rounded-lg text-sm">
            {[
              customer.street ? `${customer.street}${customer.number ? ` ${customer.number}` : ''}${customer.bus ? `/${customer.bus}` : ''}` : null,
              customer.postalCode && customer.city ? `${customer.postalCode} ${customer.city}` : null,
              customer.country && customer.country !== 'BE' ? customer.country : null,
            ].filter(Boolean).map((line, i) => (
              <div key={i}>{line}</div>
            ))}
          </div>
        )}
      </div>

      {/* Activity Content */}
      <div className="flex-1 overflow-auto p-6 space-y-4">
        {error && (
          <div className="p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            Error loading activity: {error}
          </div>
        )}

        {loadingActivity ? (
          <div className="flex items-center justify-center py-16 text-muted-foreground">
            Loading customer activity...
          </div>
        ) : !hasActivity ? (
          /* Global empty-state banner */
          <div className="flex flex-col items-center justify-center py-16 text-muted-foreground gap-2">
            <p className="text-lg font-medium">This customer has no recorded activity yet</p>
            <p className="text-sm">Sales, bicycles, orders, and repairs will appear here once created.</p>
          </div>
        ) : (
          <>
            {/* Section 1: Sales History */}
            <SalesHistorySection sales={sales} />

            {/* Section 2: Owned Bicycles */}
            <OwnedBicyclesSection bicycles={bicycles} />

            {/* Section 3: Customer Orders / Reservations */}
            <CustomerOrdersSection orders={orders} />

            {/* Section 4: Repairs */}
            <RepairsSection repairs={repairs} />

            {/* Summary Footer (when hasActivity) */}
            {hasActivity && <SummaryFooter sales={sales} repairs={repairs} bicycles={bicycles} />}
          </>
        )}
      </div>
    </div>
  )
}

