content.text:
/**
 * useCustomers — Unit tests.
 *
 * Tests:
 * - Data fetching (initial load, error handling)
 * - Pagination state management
 * - Search debouncing behavior
 */

import { describe, it, expect, vi, afterEach } from 'vitest'
import { renderHook, act, waitFor } from '@testing-library/react'
import { useCustomers } from '../useCustomers.js'
import type { CustomerPaginatedResponse, CustomerDetail } from '../../types.js'

// ---------------------------------------------------------------------------
// Mock the API module — must be hoisted to top of file for vi.mock
// ---------------------------------------------------------------------------

const mockFetchFn = vi.fn() as ReturnType<typeof vi.fn> & {
  mockResolvedValueOnce: (value: CustomerPaginatedResponse) => void
  mockRejectedValueOnce: (error: Error) => void
}

vi.mock('../../api.js', () => ({
  fetchCustomers: (...args: unknown[]) => mockFetchFn(...args),
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createMockCustomer(id: string, type: 'private' | 'company'): CustomerDetail {
  return {
    id,
    displayName: type === 'private'
      ? ['John', 'Doe'].filter(Boolean).join(' ').trim()
      : 'Acme Corp',
    type,
    firstName: type === 'private' ? 'John' : undefined,
    lastName: type === 'private' ? 'Doe' : undefined,
    companyName: type === 'company' ? 'Acme Corp' : undefined,
    vatId: null,
    phone: '+32 470 12 34 56',
    email: 'john@example.com',
    street: 'Rue du Test',
    number: '12',
    bus: null,
    postalCode: '1000',
    city: 'Brussels',
    country: 'BE',
  }
}

const mockCustomers: CustomerDetail[] = [
  createMockCustomer('cust-001', 'private'),
  createMockCustomer('cust-002', 'company'),
  createMockCustomer('cust-003', 'private'),
]

function createPaginatedResponse(
  customers: CustomerDetail[],
  totalItems: number,
  page = 1,
  pageSize = 25
): CustomerPaginatedResponse {
  return {
    customers,
    totalItems,
    currentPage: page,
    pageSize,
    totalPages: Math.ceil(totalItems / pageSize),
  }
}

// ---------------------------------------------------------------------------
// Data Fetching Tests
// ---------------------------------------------------------------------------

describe('useCustomers — data fetching', () => {
  afterEach(() => {
    vi.resetAllMocks()
  })

  it('fetches customers on initial mount', async () => {
    const mockResponse = createPaginatedResponse(mockCustomers, 3)
    ;(mockFetchFn as any).mockResolvedValueOnce(mockResponse)

    const { result } = renderHook(() => useCustomers())

    // Wait for the async fetch to complete
    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    expect(mockFetchFn).toHaveBeenCalledWith({
      page: 1,
      pageSize: 25,
    })
    expect(result.current.customers).toEqual(mockCustomers)
    expect(result.current.totalItems).toBe(3)
    expect(result.current.error).toBeNull()
  })

  it('handles API errors gracefully', async () => {
    ;(mockFetchFn as any).mockRejectedValueOnce(new Error('Network error'))

    const { result } = renderHook(() => useCustomers())

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    expect(result.current.error).toBe('Network error')
    expect(result.current.customers).toEqual([])
  })

  it('resets customers and shows error on fetch failure', async () => {
    ;(mockFetchFn as any).mockRejectedValueOnce(new Error('Server error'))

    const { result } = renderHook(() => useCustomers())

    await waitFor(() => {
      expect(result.current.error).toBe('Server error')
    })

    expect(result.current.customers).toEqual([])
  })
})

// ---------------------------------------------------------------------------
// Pagination State Management Tests
// ---------------------------------------------------------------------------

describe('useCustomers — pagination', () => {
  afterEach(() => {
    vi.resetAllMocks()
  })

  it('starts at page 1 by default', async () => {
    const mockResponse = createPaginatedResponse(mockCustomers, 3)
    ;(mockFetchFn as any).mockResolvedValueOnce(mockResponse)

    const { result } = renderHook(() => useCustomers())

    await waitFor(() => {
      expect(result.current.currentPage).toBe(1)
    })
  })

  it('navigates to a specific page via goToPage', async () => {
    const mockResponse = createPaginatedResponse(mockCustomers, 50, 2, 25)
    ;(mockFetchFn as any).mockResolvedValueOnce(mockResponse)

    const { result } = renderHook(() => useCustomers())

    await waitFor(() => {
      expect(result.current.currentPage).toBe(1)
    })

    // Navigate to page 2
    act(() => {
      result.current.goToPage(2)
    })

    expect(result.current.currentPage).toBe(2)
    expect(mockFetchFn).toHaveBeenLastCalledWith({
      page: 2,
      pageSize: 25,
    })
  })

  it('calculates totalPages correctly', async () => {
    const mockResponse = createPaginatedResponse(mockCustomers, 60, 1, 25)
    ;(mockFetchFn as any).mockResolvedValueOnce(mockResponse)

    const { result } = renderHook(() => useCustomers())

    await waitFor(() => {
      expect(result.current.totalPages).toBe(3) // ceil(60/25) = 3
    })
  })

  it('handles single page of results', async () => {
    const mockResponse = createPaginatedResponse(mockCustomers, 10, 1, 25)
    ;(mockFetchFn as any).mockResolvedValueOnce(mockResponse)

    const { result } = renderHook(() => useCustomers())

    await waitFor(() => {
      expect(result.current.totalPages).toBe(1) // ceil(10/25) = 1
    })
  })

  it('uses default page size of 25', async () => {
    const mockResponse = createPaginatedResponse(mockCustomers, 3)
    ;(mockFetchFn as any).mockResolvedValueOnce(mockResponse)

    const { result } = renderHook(() => useCustomers())

    await waitFor(() => {
      expect(result.current.pageSize).toBe(25)
    })
  })
})

// ---------------------------------------------------------------------------
// Search Debouncing Tests
// ---------------------------------------------------------------------------

describe('useCustomers — search debouncing', () => {
  afterEach(() => {
    vi.useRealTimers()
    vi.resetAllMocks()
  })

  it('does not call API immediately when setSearchTerm is called', async () => {
    const mockResponse = createPaginatedResponse(mockCustomers, 3)
    ;(mockFetchFn as any).mockResolvedValueOnce(mockResponse)

    const { result } = renderHook(() => useCustomers())

    // Wait for the initial fetch to complete
    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    // Record call count before setting search term
    const callsBefore = mockFetchFn.mock.calls.length

    // Set search term — should NOT trigger API call immediately
    act(() => {
      result.current.setSearchTerm('test')
    })

    // Immediately check: no new API call should have been made yet
    expect(mockFetchFn.mock.calls.length).toBe(callsBefore)
    // But searchTerm state should be updated
    expect(result.current.searchTerm).toBe('test')
  })

  it('calls API after debounce delay', async () => {
    vi.useFakeTimers()

    const mockResponse = createPaginatedResponse(mockCustomers, 3)
    ;(mockFetchFn as any).mockResolvedValueOnce(mockResponse)

    const { result } = renderHook(() => useCustomers())

    // Flush async state updates from initial render (replaces waitFor with fake timers)
    await act(async () => {})

    // Record call count before setting search term
    const callsBefore = mockFetchFn.mock.calls.length

    // Set search term
    act(() => {
      result.current.setSearchTerm('john')
    })

    // Advance time by less than debounce — no API call yet
    act(() => {
