/**
 * useCustomerActivity — Unit tests.
 *
 * Tests:
 * - Data fetching for all activity sections (sales, bicycles, orders, repairs)
 * - Empty state handling
 * - Error handling per section
 */

import { describe, it, expect, vi, afterEach } from 'vitest'
import { renderHook, act, waitFor } from '@testing-library/react'
import { useCustomerActivity } from '../useCustomerActivity.js'
import type { CustomerSale, CustomerBicycle, CustomerOrder } from '../../types.js'

// ---------------------------------------------------------------------------
// Mock the API module
// ---------------------------------------------------------------------------

const mockFetchSales = vi.fn()
const mockFetchBicycles = vi.fn()
const mockFetchOrders = vi.fn()
const mockFetchRepairs = vi.fn()

vi.mock('../../api.js', () => ({
  fetchCustomerSales: (...args: unknown[]) => mockFetchSales(...args),
  fetchCustomerBicycles: (...args: unknown[]) => mockFetchBicycles(...args),
  fetchCustomerOrders: (...args: unknown[]) => mockFetchOrders(...args),
  fetchRepairsByBicycleIds: (...args: unknown[]) => mockFetchRepairs(...args),
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createMockSale(id: string): CustomerSale {
  return {
    id,
    saleNumber: `SA-${id.slice(-4)}`,
    sourceType: 'direct_sale',
    sourceId: null,
    status: 'completed',
    subtotalNet: 1000,
    vatTotal: 210,
    totalGross: 1210,
    createdAt: Date.now(),
  }
}

function createMockBicycle(id: string): CustomerBicycle {
  return {
    id,
    source: 'customer_owned',
    brand: 'TestBrand',
    model: 'TestModel',
    year: 2024,
    color: 'Red',
    isLease: false,
    status: 'in_shop',
  }
}

function createMockOrder(id: string): CustomerOrder {
  return {
    id,
    orderNumber: `CO-${id.slice(-4)}`,
    status: 'pending',
    totalPriceNet: 5000,
    expectedDeliveryDate: null,
    createdAt: Date.now(),
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('useCustomerActivity — data fetching', () => {
  afterEach(() => {
    vi.resetAllMocks()
  })

  it('fetches all activity sections on mount', async () => {
    const mockSales = [createMockSale('sale-001')]
    const mockBicycles = [createMockBicycle('bike-001')]
    const mockOrders = [createMockOrder('order-001')]
    const mockRepairs = [{ id: 'repair-001', bicycle_id: 'bike-001', status: 'completed', planned_date: null, pickup_date: null, completed_at: Date.now(), created_at: Date.now(), bicycle_brand: 'TestBrand', bicycle_model: 'TestModel' }]

    mockFetchSales.mockResolvedValueOnce(mockSales)
    mockFetchBicycles.mockResolvedValueOnce(mockBicycles)
    mockFetchOrders.mockResolvedValueOnce(mockOrders)
    mockFetchRepairs.mockResolvedValueOnce(mockRepairs)

    const { result } = renderHook(() => useCustomerActivity('customer-001'))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    expect(result.current.sales).toEqual(mockSales)
    expect(result.current.bicycles).toEqual(mockBicycles)
    expect(result.current.orders).toEqual(mockOrders)
    expect(result.current.repairs.length).toBe(1)
    expect(result.current.hasActivity).toBe(true)
  })

  it('shows no activity when all sections are empty', async () => {
    mockFetchSales.mockResolvedValueOnce([])
    mockFetchBicycles.mockResolvedValueOnce([])
    mockFetchOrders.mockResolvedValueOnce([])

    const { result } = renderHook(() => useCustomerActivity('customer-empty'))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    expect(result.current.sales).toEqual([])
    expect(result.current.bicycles).toEqual([])
    expect(result.current.orders).toEqual([])
    expect(result.current.repairs).toEqual([])
    expect(result.current.hasActivity).toBe(false)
  })

  it('skips repairs fetch when no bicycles exist', async () => {
    mockFetchSales.mockResolvedValueOnce([])
    mockFetchBicycles.mockResolvedValueOnce([])
    mockFetchOrders.mockResolvedValueOnce([])

    const { result } = renderHook(() => useCustomerActivity('customer-no-bikes'))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    // Repairs should not be fetched when there are no bicycles
    expect(mockFetchRepairs).not.toHaveBeenCalled()
    expect(result.current.repairs).toEqual([])
  })

  it('handles individual section errors gracefully', async () => {
    mockFetchSales.mockRejectedValueOnce(new Error('Sales API error'))
    mockFetchBicycles.mockResolvedValueOnce([createMockBicycle('bike-001')])
    mockFetchOrders.mockRejectedValueOnce(new Error('Orders API error'))
    mockFetchRepairs.mockResolvedValueOnce([])

    const { result } = renderHook(() => useCustomerActivity('customer-errors'))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    // Sales should be empty (error caught), bicycles should load, orders should be empty
    expect(result.current.sales).toEqual([])
    expect(result.current.bicycles.length).toBe(1)
    expect(result.current.orders).toEqual([])
  })

  it('sorts repairs chronologically (oldest first)', async () => {
    const mockBicycles = [createMockBicycle('bike-001')]
    const newerRepair = { id: 'repair-new', bicycle_id: 'bike-001', status: 'in_progress', planned_date: null, pickup_date: null, completed_at: null, created_at: Date.now(), bicycle_brand: 'Brand', bicycle_model: 'Model' }
    const olderRepair = { id: 'repair-old', bicycle_id: 'bike-001', status: 'completed', planned_date: null, pickup_date: null, completed_at: Date.now() - 86400000, created_at: Date.now() - 86400000, bicycle_brand: 'Brand', bicycle_model: 'Model' }

    mockFetchSales.mockResolvedValueOnce([])
    mockFetchBicycles.mockResolvedValueOnce(mockBicycles)
    mockFetchOrders.mockResolvedValueOnce([])
    // Return newer first to test sorting
    mockFetchRepairs.mockResolvedValueOnce([newerRepair, olderRepair])

    const { result } = renderHook(() => useCustomerActivity('customer-sort'))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    // Should be sorted oldest first
    expect(result.current.repairs[0].id).toBe('repair-old')
    expect(result.current.repairs[1].id).toBe('repair-new')
  })

  it('respects VOLUME_LIMIT of 50 for repairs', async () => {
    const mockBicycles = [createMockBicycle('bike-001')]
    // Create 60 repairs (more than limit)
    const manyRepairs = Array.from({ length: 60 }, (_, i) => ({
      id: `repair-${i}`,
      bicycle_id: 'bike-001',
      status: 'completed',
      planned_date: null,
      pickup_date: null,
      completed_at: Date.now() - (60 - i) * 86400000,
      created_at: Date.now() - (60 - i) * 86400000,
      bicycle_brand: 'Brand',
      bicycle_model: 'Model',
    }))

    mockFetchSales.mockResolvedValueOnce([])
    mockFetchBicycles.mockResolvedValueOnce(mockBicycles)
    mockFetchOrders.mockResolvedValueOnce([])
    mockFetchRepairs.mockResolvedValueOnce(manyRepairs)

    const { result } = renderHook(() => useCustomerActivity('customer-limit'))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    // Should be limited to 50
    expect(result.current.repairs.length).toBe(50)
  })
})

